import{createWorldRuntime}from'./world.js';import{createVNController}from'./vn.js';import{outcomeSummary,record}from'./model.js';const $=s=>document.querySelector(s);const runtime=createWorldRuntime({canvas:$('#world'),hudTime:$('#hud-time'),promptEl:$('#interaction-prompt'),noticeEl:$('#notice'),situationEl:$('#situation')});const debrief=$('#debrief'),summary=$('#debrief-summary'),form=$('#debrief-form');function persist(extra=null){if(extra)record(runtime.state,'debrief',extra);const runs=JSON.parse(localStorage.getItem('md-v007d-runs')||'[]');const payload={savedAt:new Date().toISOString(),state:runtime.state};const i=runs.findIndex(r=>r.state?.runId===runtime.state.runId);if(i>=0)runs[i]=payload;else runs.push(payload);localStorage.setItem('md-v007d-runs',JSON.stringify(runs));}function showDebrief(){runtime.setPaused(true);runtime.setInputContext('debrief');summary.replaceChildren(...outcomeSummary(runtime.state).map(t=>{const li=document.createElement('li');li.textContent=t;return li;}));debrief.hidden=false;persist();}const vn=createVNController({vn:$('#vn'),titleEl:$('#vn-title'),speakerEl:$('#vn-speaker'),textEl:$('#vn-text'),choicesEl:$('#vn-choices'),runtime});runtime.setSceneHandler(()=>vn.start());runtime.setEndHandler(showDebrief);let last=performance.now();function frame(now){const dt=Math.min(.05,(now-last)/1000);last=now;runtime.tick(dt);runtime.draw();requestAnimationFrame(frame);}requestAnimationFrame(t=>{last=t;requestAnimationFrame(frame);});window.addEventListener('keydown',e=>{const tag=document.activeElement?.tagName?.toLowerCase();if(['input','textarea','select'].includes(tag))return;const k=e.key.toLowerCase();if(vn.active){if(vn.handleKey(k))e.preventDefault();return;}if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright'].includes(k)){runtime.setKey(k,true);e.preventDefault();}if((k==='e'||k==='enter')&&!e.repeat){runtime.interact();e.preventDefault();}if(k==='tab'&&!e.repeat){runtime.cycleTarget();e.preventDefault();}});window.addEventListener('keyup',e=>runtime.setKey(e.key.toLowerCase(),false));window.addEventListener('blur',runtime.clearKeys);$('#finish-run').onclick=showDebrief;$('#reset-run').onclick=()=>{debrief.hidden=true;form.reset();runtime.reset();};$('#export-trace').onclick=()=>{const runs=JSON.parse(localStorage.getItem('md-v007d-runs')||'[]');const blob=new Blob([JSON.stringify(runs,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`managed-decline-v007d-traces-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href);};form.addEventListener('submit',e=>{e.preventDefault();persist(Object.fromEntries(new FormData(form).entries()));runtime.showNotice('Debrief saved locally.');});
